      r4c: say('khala', 'لَا بَأْسَ. صَفِّقْ مَعَنَا إِذَنْ!', 'laa baʾs. ṣaffiq maʿanaa idhan!', 'No problem. Clap along with us then!', 'b1', ['لَا بَأْسَ. صَفِّقِي مَعَنَا إِذَنْ!', 'laa baʾs. ṣaffiqii maʿanaa idhan!']),
